theorem Tx.legacy_of_legacy? {body : TxBody} {tx : Tx}
    (h : Tx.legacy? body = some tx) :
    ∃ hne : body.inputs.val ≠ [], tx = Tx.legacy body hne

theorem Tx.spentCoins_length {tx : Tx} {utxos : UtxoSet}
    (h : ∀ o ∈ tx.body.spends, o ∈ utxos) :
    (tx.spentCoins utxos).length = tx.body.inputs.val.length

theorem Tx.creates_do_not_overwrite_after_spend
    {scriptOk : ScriptCheck} {utxos : UtxoSet}
    {clock : LockTimeClock} {ctx : TxContext} {tx : Tx}
    (h : Tx.Admissible scriptOk utxos clock ctx tx) :
    ∀ o ∈ tx.body.creates.map Prod.fst, o ∉ utxos.spend tx.body.spends

theorem UtxoSet.totalValue_apply_le_of_admissible {scriptOk : ScriptCheck}
    {utxos : UtxoSet} {clock : LockTimeClock} {ctx : TxContext}
    {provenance : Provenance} {tx : Tx} (hwf : tx.WellFormed)
    (hadm : Tx.Admissible scriptOk utxos clock ctx tx) :
    totalValue (utxos.apply provenance tx.body) ≤ utxos.totalValue

theorem root_binding_of_length_eq {xs ys : List Hash256}
    (hlen : xs.length = ys.length) (hroot : root xs = root ys) :
    xs = ys ∨ Sha256.Collision

theorem CollisionResistant.comp {α β γ : Type*} {f : α → β} {g : β → γ}
    (hf : CollisionResistant f) (hg : CollisionResistant g) :
    CollisionResistant (g ∘ f)

theorem TxBody.mem_creates (body : TxBody) {i : Nat}
    (hi : i < body.outputs.val.length) :
    (⟨body.txid, UInt32.ofNat i⟩, body.outputs.val[i]) ∈ body.creates

theorem UtxoSet.lookup_apply_output {utxos : UtxoSet} {provenance : Provenance}
    {body : TxBody} (houtputs : body.outputs.val.length ≤ 2 ^ 32) {i : Nat}
    (hi : i < body.outputs.val.length) :
    (utxos.apply provenance body).lookup ⟨body.txid, UInt32.ofNat i⟩
      = some ⟨body.outputs.val[i], provenance⟩

theorem UtxoSet.lookup_spend_of_notMem {utxos : UtxoSet} {outpoints : List OutPoint}
    {o : OutPoint} (h : o ∉ outpoints) :
    (utxos.spend outpoints).lookup o = utxos.lookup o

theorem UtxoSet.lookup_spend_of_mem {utxos : UtxoSet} {outpoints : List OutPoint}
    {o : OutPoint} (h : o ∈ outpoints) :
    (utxos.spend outpoints).lookup o = none

theorem UtxoSet.lookup_create_of_notMem {utxos : UtxoSet} {coins : List (OutPoint × Coin)}
    {o : OutPoint} (h : o ∉ coins.map Prod.fst) :
    (utxos.create coins).lookup o = utxos.lookup o

theorem UtxoSet.lookup_create_of_mem {utxos : UtxoSet} {coins : List (OutPoint × Coin)}
    (hkeys : (coins.map Prod.fst).Nodup) {o : OutPoint} {c : Coin} (hmem : (o, c) ∈ coins) :
    (utxos.create coins).lookup o = some c

theorem UtxoSet.totalValue_insert {utxos : UtxoSet} {o : OutPoint} {c : Coin}
    (h : o ∉ utxos) :
    totalValue (utxos.insert o c) = c.output.value.toNat + utxos.totalValue

theorem zipWith_map_map_left_right {f : γ → α} {g : γ → β} {mk : α → β → γ}
    (h : ∀ c, mk (f c) (g c) = c) (l : List γ) :
    zipWith mk (l.map f) (l.map g) = l

theorem Bytes.parts_of_ofListPadLeft? {n : Nat} {padding : UInt8}
    {bs : List UInt8} {out : Bytes n}
    (h : Bytes.ofListPadLeft? padding bs = some out) :
    out.val.take (n - bs.length) = List.replicate (n - bs.length) padding ∧
      out.val.drop (n - bs.length) = bs

theorem Bytes.parts_of_ofListPadRight? {n : Nat} {padding : UInt8}
    {bs : List UInt8} {out : Bytes n}
    (h : Bytes.ofListPadRight? padding bs = some out) :
    out.val.take bs.length = bs ∧
      out.val.drop bs.length = List.replicate (n - bs.length) padding

theorem Bytes.head?_of_ofListPadLeft? {n : Nat} {padding : UInt8}
    {bs : List UInt8} {out : Bytes n}
    (h : Bytes.ofListPadLeft? padding bs = some out) :
    out.val.head? = some padding

theorem Bytes.getLast?_of_ofListPadRight? {n : Nat} {padding : UInt8}
    {bs : List UInt8} {out : Bytes n}
    (h : Bytes.ofListPadRight? padding bs = some out) :
    out.val.getLast? = some padding

theorem Bytes.ofListTruncateLeft?_of_ofListPadLeft? {n : Nat} {padding : UInt8}
    {bs : List UInt8} {out : Bytes n}
    (h : Bytes.ofListPadLeft? padding bs = some out) :
    Bytes.ofListTruncateLeft? (n := bs.length) out.val =
      Bytes.ofListExact? (n := bs.length) bs

theorem Bytes.ofListTruncateRight?_of_ofListPadRight? {n : Nat} {padding : UInt8}
    {bs : List UInt8} {out : Bytes n}
    (h : Bytes.ofListPadRight? padding bs = some out) :
    Bytes.ofListTruncateRight? (n := bs.length) out.val =
      Bytes.ofListExact? (n := bs.length) bs

theorem abstractParse_bind {α β : Type} (p : Option (α × ByteSlice))
    {f : α × ByteSlice → Option (β × ByteSlice)}
    {g : α × List UInt8 → Option (β × List UInt8)}
    (h : ∀ a s, abstractParse (f (a, s)) = g (a, s.toList)) :
    abstractParse (p.bind f) = (abstractParse p).bind g

private theorem decodeTx_eq_specDispatch (bs : List UInt8) :
    decodeTx bs
      = (Codec.decode (α := UInt32) bs).bind fun p => specDispatch p.1 p.2

theorem witnessCommitment_binding {r₁ r₂ : Hash256} {v₁ v₂ : Bytes 32}
    (h : witnessCommitment r₁ v₁ = witnessCommitment r₂ v₂) :
    (r₁ = r₂ ∧ v₁ = v₂) ∨ Sha256.Collision

theorem openings_with_distinct_bits_are_distinct {Nonce : Type}
    (left right : Opening Nonce)
    (hdiff : left.bit ≠ right.bit) : left ≠ right

private theorem spineCanonical_ofList_of_treeMutation :
    ∀ (k : Nat) (xs : List Hash256),
      treeMutation (ofList xs k) = false → (ofList xs k).spineCanonical = true
